-- =====================================================
-- DZIEŃ 4 — „Poniedziałek w GIKO”, 8 zadań typu „Narzędzie + polecenie” (4.1–4.8)
-- Treść: docs/dzien4_zadania.md. 1:1.
-- Nie dotyka graczy, prób, biblioteki ani zadań innych dni.
-- Stare zadania Dnia 4 są wyłączane flagą active, nie usuwane.
-- Moduł zostaje zablokowany; trener odblokowuje go i grupy 4.1–4.3 | 4.4–4.6 | 4.7–4.8 (bloki 1–3).
-- Zaliczenie: wynik ≥ 40 (krok 2 żółty lub zielony) — domyślny próg level_lock dla zadań bez stref.
-- =====================================================

UPDATE public.levels SET active = false
WHERE module_id = (SELECT id FROM public.modules WHERE day_number = 4)
  AND (code IS NULL OR code NOT IN ('4.1', '4.2', '4.3', '4.4', '4.5', '4.6', '4.7', '4.8'));

UPDATE public.modules
SET title = 'Poniedziałek w GIKO', total_levels = 8, lives_enabled = false
WHERE day_number = 4;

WITH day4 AS (
  SELECT id FROM public.modules WHERE day_number = 4
),
src (code, sort_order, block, title, task_description, config) AS (VALUES

('4.1', 1, 1, 'Zdjęcie produktu do sklepu',
 $t$Krok 1 · Wybierz narzędzie. Krok 2 · Napisz polecenie.$t$,
 $j${"label":"Zadanie 4.1","block_name":"Zadania 4.1–4.3","situation":"Zrobiłeś telefonem zdjęcie produktu na biurku. Krzywo, ciemno, w tle kabel. Zdjęcie ma trafić do sklepu internetowego.","tool":{"correct":"nano_banana","accepted":["nano_banana","copilot_chat"],"why":"Nano Banana świetnie edytuje zdjęcia. Produkt jest publiczny, bo i tak trafi do sklepu.","hints":{"perplexity":"To narzędzia do szukania i czytania, a tu trzeba zmienić obraz.","notebooklm":"To narzędzia do szukania i czytania, a tu trzeba zmienić obraz.","elevenlabs":"ElevenLabs robi głos, a tu potrzebujesz obrazu.","outlook":"Outlook to poczta. Zdjęcie edytujesz w czacie z grafiką."},"criteria":["co zmienić: tło, światło","format albo przeznaczenie: kwadrat, do sklepu","czego nie zmieniać: logo, napisy, kolor produktu"],"note":"Brak punktu 3 → ŻÓŁTA z podpowiedzią „Dopisz: nie zmieniaj logo ani napisów na produkcie. AI lubi je poprawiać.”","must":[{"any":[3],"hint":"Dopisz: nie zmieniaj logo ani napisów na produkcie. AI lubi je poprawiać."}],"preview":"Opisz w 2–3 zdaniach, jak będzie wyglądało zdjęcie. Jeśli polecenie nie zabrania zmian w produkcie, dodaj: „Uwaga: logo na produkcie mogło się zmienić.”","reference":"Zmień tło na białe, dodaj miękkie światło, format kwadratowy do sklepu internetowego. Nie zmieniaj logo, napisów ani koloru produktu."}}$j$::jsonb),

('4.2', 2, 1, 'Film dla klienta z Czech',
 $t$Krok 1 · Wybierz narzędzie. Krok 2 · Co sprawdzisz, zanim wyślesz film klientowi? Zaznacz 3.$t$,
 $j${"label":"Zadanie 4.2","block_name":"Zadania 4.1–4.3","situation":"Masz 2-minutowy film instruktażowy po polsku, w którym mówi Wasz kierownik. Klient z Czech prosi o wersję po czesku.","tool":{"correct":"elevenlabs","accepted":["elevenlabs"],"why":"ElevenLabs tłumaczy nagranie i zachowuje głos mówiącego.","hints":{"outlook":"Tu chodzi o głos w filmie. Które narzędzie robiło dubbing reklamy?","copilot_chat":"Tu chodzi o głos w filmie. Które narzędzie robiło dubbing reklamy?","perplexity":"Tu chodzi o głos w filmie. Które narzędzie robiło dubbing reklamy?","notebooklm":"Tu chodzi o głos w filmie. Które narzędzie robiło dubbing reklamy?","nano_banana":"Tu chodzi o głos w filmie. Które narzędzie robiło dubbing reklamy?"},"checks":{"question":"Co sprawdzisz, zanim wyślesz film klientowi? Zaznacz 3.","options":[{"text":"Czy film ma ładną muzykę","correct":false},{"text":"Zgodę kierownika na użycie jego głosu","correct":true},{"text":"Czy plik ma mniej niż 100 MB","correct":false},{"text":"Tłumaczenie: ktoś znający czeski albo tłumaczenie zwrotne na polski","correct":true},{"text":"Oznaczenie, że wersja czeska powstała z pomocą AI","correct":true},{"text":"Czy klient lubi filmy","correct":false}],"xp_first":70,"xp_later":40,"hint":"Pamiętasz trzy zasady obrazu i głosu ze slajdu?"}}}$j$::jsonb),

('4.3', 3, 1, 'Plakat z nowymi godzinami',
 $t$Krok 1 · Wybierz narzędzie. Krok 2 · Napisz polecenie.$t$,
 $j${"label":"Zadanie 4.3","block_name":"Zadania 4.1–4.3","situation":"Od 1 stycznia 2027 biuro pracuje w nowych godzinach: pon.–pt. 7:30–15:30. Potrzebujesz plakatu A4 na drzwi.","tool":{"correct":"copilot_chat","accepted":["copilot_chat","nano_banana"],"why":"Oba robią grafikę. Plakat jest publiczny, więc darmowe narzędzie też jest w porządku.","hints":{"perplexity":"Tu nic nie szukasz, tylko tworzysz obraz.","notebooklm":"Tu nic nie szukasz, tylko tworzysz obraz.","elevenlabs":"ElevenLabs robi głos, nie grafikę.","outlook":"Outlook to poczta. Grafikę zrobisz w czacie."},"criteria":["dokładny tekst na plakacie (godziny)","styl albo kolory","format A4 albo czego nie chcesz (np. bez zdjęć ludzi)"],"note":"Brak dokładnych godzin → ŻÓŁTA z podpowiedzią „Wpisz dokładny tekst, inaczej AI wymyśli godziny.”","must":[{"any":[1],"pattern":"7[:.]?30[\\s\\S]*15[:.]?30","strict":true,"hint":"Wpisz dokładny tekst, inaczej AI wymyśli godziny."}],"preview":"Opisz plakat w 2–3 zdaniach. Na końcu przypomnij: „Sprawdź polskie litery na plakacie. AI robi w nich literówki.”","reference":"Plakat A4: „Nowe godziny pracy biura od 1 stycznia 2027: pon.–pt. 7:30–15:30”. Styl prosty, firmowy, granat i biel. Bez zdjęć ludzi."}}$j$::jsonb),

('4.4', 4, 2, 'Szef pyta o płacę minimalną',
 $t$Krok 1 · Wybierz narzędzie. Krok 2 · Napisz polecenie.$t$,
 $j${"label":"Zadanie 4.4","block_name":"Zadania 4.4–4.6","situation":"Szef liczy budżet na przyszły rok: „Ile od stycznia wynosi płaca minimalna?”","tool":{"correct":"perplexity","accepted":["perplexity","copilot_chat"],"why":"Temat jest publiczny, a liczy się aktualność. Perplexity pokazuje źródła z datą.","hints":{"notebooklm":"NotebookLM czyta Twoje pliki, a tu potrzebujesz aktualnej informacji z internetu.","nano_banana":"Tu potrzebujesz faktu, nie obrazu ani głosu.","elevenlabs":"Tu potrzebujesz faktu, nie obrazu ani głosu.","outlook":"Outlook nie szuka w internecie. Wybierz narzędzie do faktów."},"criteria":["konkretny okres (od 1 stycznia 2027)","prośba o źródło albo link","brutto albo data publikacji źródła"],"note":"Brak prośby o źródło → ŻÓŁTA z podpowiedzią „Dopisz: podaj źródło i datę. Bez tego nie sprawdzisz, czy liczba jest aktualna.”","must":[{"any":[2],"hint":"Dopisz: podaj źródło i datę. Bez tego nie sprawdzisz, czy liczba jest aktualna."}],"preview":"Ten fakt jest sprawdzony i możesz go użyć: od 1 stycznia 2027 r. płaca minimalna wynosi 4950 zł brutto miesięcznie (rozporządzenie Rady Ministrów z 14 września 2026 r., Dz.U. 2026 poz. 1213). Źródła pokaż jako [ŹRÓDŁO 1], [ŹRÓDŁO 2] z dopiskiem „z datą”.","reference":"Ile wynosi płaca minimalna w Polsce od 1 stycznia 2027 r., brutto miesięcznie? Podaj źródło i datę jego publikacji."}}$j$::jsonb),

('4.5', 5, 2, 'Instrukcja producenta',
 $t$Krok 1 · Wybierz narzędzie. Krok 2 · Napisz polecenie.$t$,
 $j${"label":"Zadanie 4.5","block_name":"Zadania 4.4–4.6","situation":"Klient pyta, jak często wymieniać filtr w urządzeniu. Odpowiedź jest gdzieś w 40-stronicowej instrukcji producenta, którą każdy może pobrać ze strony producenta.","tool":{"correct":"notebooklm","accepted":["notebooklm","copilot_chat"],"why":"NotebookLM odpowiada tylko na podstawie wgranego dokumentu i pokazuje, skąd wziął odpowiedź. Instrukcja jest publiczna.","hints":{"perplexity":"Perplexity szuka w całym internecie, a Ty masz już konkretny dokument.","nano_banana":"Tu potrzebujesz odpowiedzi z dokumentu.","elevenlabs":"Tu potrzebujesz odpowiedzi z dokumentu.","outlook":"Outlook to poczta. Dokument wgrywasz do narzędzia, które czyta pliki."},"criteria":["konkretne pytanie (jak często wymieniać filtr)","prośba o stronę albo cytat","„jeśli tego nie ma w dokumencie, napisz to”"],"note":"Brak punktu 2 i 3 → ŻÓŁTA z podpowiedzią „Poproś o numer strony: wtedy w 10 sekund sprawdzisz, czy AI nie zmyśla.”","must":[{"any":[2,3],"hint":"Poproś o numer strony: wtedy w 10 sekund sprawdzisz, czy AI nie zmyśla."}],"preview":"Odpowiedź w 1–2 zdaniach z miejscem [CO ILE WYMIANA] i [STRONA]. Nie podawaj konkretnej liczby.","reference":"Jak często według tej instrukcji trzeba wymieniać filtr? Podaj numer strony. Jeśli tego nie ma w dokumencie, napisz to."}}$j$::jsonb),

('4.6', 6, 2, 'Umowa z klientem (pułapka)',
 $t$Krok 1 · Wybierz narzędzie. Krok 2 · Napisz polecenie.$t$,
 $j${"label":"Zadanie 4.6","block_name":"Zadania 4.4–4.6","situation":"Szef: „Na jutro chcę wiedzieć, co w umowie z firmą Weber jest o karach umownych.” Umowa ma 20 stron.","tool":{"correct":"copilot_chat","accepted":["copilot_chat"],"why":"Umowa z klientem to firmowy dokument. Tylko Copilot na koncie firmowym ma ochronę danych firmy (zielona tarcza).","hints":{"notebooklm":"Kusi, bo czyta dokumenty. Ale to darmowe konto prywatne, a umowa jest firmowa. Tylko Copilot na koncie firmowym.","perplexity":"Nie szukasz w internecie i nie wklejasz umowy do darmowego narzędzia.","nano_banana":"Tu potrzebujesz odpowiedzi z dokumentu.","elevenlabs":"Tu potrzebujesz odpowiedzi z dokumentu.","outlook":"Blisko, ale umowę wgrywasz do Copilot Chat i tam zadajesz pytania."},"criteria":["czego szukać (kary umowne: za co, ile)","forma (punkty, krótko)","prośba o numer paragrafu"],"note":"Tu nazwa klienta jest w porządku (Copilot na koncie firmowym), nie dawaj za nią czerwonej.","must":[],"preview":"3 punkty z miejscami [ZA CO], [KWOTA], [§]. Nie wymyślaj treści umowy.","reference":"Wypisz w punktach wszystkie kary umowne z tej umowy: za co, w jakiej wysokości i w którym paragrafie."}}$j$::jsonb),

('4.7', 7, 3, 'Klient z Lipska',
 $t$Krok 1 · Wybierz narzędzie. Krok 2 · Napisz polecenie.$t$,
 $j${"label":"Zadanie 4.7","block_name":"Zadania 4.7–4.8","situation":"Przychodzi mail po niemiecku:","blocks":[{"text":"„Sehr geehrte Damen und Herren, am 28. Oktober haben wir die Bestellung 2026/1187 aufgegeben. Laut Bestätigung sollte die Lieferung in KW 46 kommen. Die Woche ist fast vorbei und wir haben keine Information. Außerdem brauchen unsere Mitarbeiter eine Anleitung auf Deutsch. Bitte nennen Sie uns den neuen Liefertermin. Mit freundlichen Grüßen, Markus Weber, Weber GmbH, Leipzig“","mail":true},{"title":"Fakty do odpowiedzi","text":"nowy termin dostawy to tydzień 48 (23–27 listopada 2026), instrukcję po niemiecku wyślemy w piątek."}],"tool":{"correct":"outlook","accepted":["outlook","copilot_chat"],"why":"Mail jest w Outlooku, więc Copilot przy mailu od razu go widzi. Dane klienta zostają na koncie firmowym.","hints":{"perplexity":"W mailu jest nazwisko klienta i numer zamówienia. Tylko Copilot na koncie firmowym.","notebooklm":"W mailu jest nazwisko klienta i numer zamówienia. Tylko Copilot na koncie firmowym.","nano_banana":"W mailu jest nazwisko klienta i numer zamówienia. Tylko Copilot na koncie firmowym.","elevenlabs":"W mailu jest nazwisko klienta i numer zamówienia. Tylko Copilot na koncie firmowym."},"criteria":["streszczenie po polsku albo prośba o odpowiedź po niemiecku","fakty: tydzień 48 i instrukcja w piątek","ton (uprzejmie, krótko) albo prośba o tłumaczenie zwrotne na polski do sprawdzenia"],"note":"Brak faktów → ŻÓŁTA z podpowiedzią „Podaj nowy termin, inaczej AI go wymyśli.”","must":[{"any":[2],"pattern":"48|23\\s*[–-]\\s*27","hint":"Podaj nowy termin, inaczej AI go wymyśli."}],"preview":"Napisz krótką odpowiedź po niemiecku (3–4 zdania) z faktami podanymi w poleceniu, a pod nią jedno zdanie po polsku: co jest w odpowiedzi. Użyj tylko faktów z sytuacji.","reference":"Streść ten mail po polsku w 3 punktach. Potem napisz uprzejmą odpowiedź po niemiecku: nowy termin dostawy to tydzień 48 (23–27 listopada), instrukcję po niemiecku wyślemy w piątek. Na końcu przetłumacz odpowiedź na polski, żebym mógł ją sprawdzić."}}$j$::jsonb),

('4.8', 8, 3, 'Notatka z zebrania',
 $t$Krok 1 · Wybierz narzędzie. Krok 2 · Napisz polecenie.$t$,
 $j${"label":"Zadanie 4.8","block_name":"Zadania 4.7–4.8","situation":"Masz zdjęcie odręcznej notatki z zebrania. Jedno imię jest nieczytelne. Treść notatki:","blocks":[{"text":"„Zebranie 16.11: Ania – oferta dla Webera do śr. · Marek – zamówić kartony do pt. · Tomek – tel. do p. K. jutro · M??? – raport sprzedaży do 25.11“","mail":true}],"tool":{"correct":"copilot_chat","accepted":["copilot_chat"],"why":"Copilot Chat czyta zdjęcia. Notatka z zebrania to sprawy firmy, więc konto firmowe.","hints":{"notebooklm":"Notatka z zebrania to firmowe sprawy. Tylko Copilot na koncie firmowym.","perplexity":"Notatka z zebrania to firmowe sprawy. Tylko Copilot na koncie firmowym.","nano_banana":"Notatka z zebrania to firmowe sprawy. Tylko Copilot na koncie firmowym.","elevenlabs":"Notatka z zebrania to firmowe sprawy. Tylko Copilot na koncie firmowym.","outlook":"Zdjęcie wgrywasz do Copilot Chat. W Outlooku wyślesz potem gotową tabelę."},"criteria":["tabela z kolumnami: zadanie, kto, termin","„jeśli czegoś nie odczytasz, wpisz [NIECZYTELNE]”","dodatkowo: mail do zespołu albo sortowanie po terminie"],"note":"Brak punktu 2 → ŻÓŁTA z podpowiedzią „Dopisz: jeśli czegoś nie odczytasz, wpisz [NIECZYTELNE]. Inaczej AI zgadnie imię.”","must":[{"any":[2],"pattern":"nieczyteln","hint":"Dopisz: jeśli czegoś nie odczytasz, wpisz [NIECZYTELNE]. Inaczej AI zgadnie imię."}],"preview":"Pokaż tabelę z 4 wierszami z treści notatki. Jeśli polecenie zawiera [NIECZYTELNE], w ostatnim wierszu wpisz [NIECZYTELNE]. Jeśli nie, wpisz „Mariusz” i dodaj: „Uwaga: AI zgadło imię, którego nie dało się odczytać.”","reference":"Zrób z tego zdjęcia tabelę z kolumnami: zadanie, kto, termin. Jeśli czegoś nie możesz odczytać, wpisz [NIECZYTELNE] zamiast zgadywać."}}$j$::jsonb)
),
upd AS (
  UPDATE public.levels l
  SET level_number = s.sort_order, sort_order = s.sort_order, block = s.block, type = 'tool_prompt',
      title = s.title, xp_reward = 100, boss_dialogue = s.config->>'situation',
      task_description = s.task_description, goal_description = NULL,
      broken_prompt = NULL, blind_option_a = NULL, blind_option_b = NULL, blind_correct = NULL,
      config = s.config, active = true
  FROM src s, day4
  WHERE l.module_id = day4.id AND l.code = s.code
  RETURNING l.code
)
INSERT INTO public.levels (module_id, level_number, sort_order, block, code, title, type, xp_reward,
                           boss_dialogue, task_description, goal_description, config, active)
SELECT day4.id, s.sort_order, s.sort_order, s.block, s.code, s.title, 'tool_prompt', 100,
       s.config->>'situation', s.task_description, NULL, s.config, true
FROM src s, day4
WHERE s.code NOT IN (SELECT code FROM upd);
